#[test]
fn every_index_a_full_list_hands_out_can_be_revoked() {
    let mut list = StatusList::new(64);
    let indexes: Vec<usize> = std::iter::from_fn(|| list.allocate()).collect();
    assert_eq!(indexes.first(), Some(&1), "issued credentials already carry indexes from 1");
    assert_eq!(indexes.len(), 64);
    for &index in &indexes {
        list.set(index, true);
    }
    let decoded = StatusList::decode(&list.encode(), 64).unwrap();
    let lost: Vec<usize> = indexes.iter().copied().filter(|&i| !list.is_set(i) || !decoded.is_set(i)).collect();
    assert!(lost.is_empty(), "revocations that did not take: {lost:?}");
}
EOF
