/// Setting kind of a webhook subscription.
pub const WEBHOOK_KIND: &str = "webhook";

/// The subscription an outcome is recorded against when the tenant's
/// subscriber list could not be read in time, so no subscriber can be named.
pub const ALL_SUBSCRIPTIONS: &str = "*";

}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeliveryEvent {
    pub tenant: String,
    pub subscription: String,
    pub outcome: Outcome,
}

        let deadline = Instant::now() + DELIVERY_DEADLINE;
        let tenant = change.issuer.as_str();
        let body: Arc<[u8]> = payload(change).into();
        let Ok(subscriptions) = tokio::time::timeout_at(deadline, self.subscriptions(tenant)).await else {
            let reason = format!("subscription list not read within {DELIVERY_DEADLINE:?} of the change");
            self.sink.record(DeliveryEvent {
                tenant: tenant.to_string(),
                subscription: ALL_SUBSCRIPTIONS.to_string(),
                outcome: Outcome::Failed { reason },
            });
            self.canary_ok.store(false, Ordering::SeqCst);
            return;
        };

