cd /tmp/cold-N17-train/.git/cc-tmp/claude-0/-tmp-cold-N17-train/dd38d7d5-6a72-4f21-becd-933559132567/scratchpad/e2e && cat > bin/aliasing.dart <<'EOF'
import 'dart:convert';
import 'dart:io';

import 'package:credentials_app/src/credential_store.dart';
import 'package:credentials_app/src/held_credential.dart';
import 'package:credentials_app/src/issuer_client.dart';
import 'package:credentials_app/src/wallet_service.dart';

class Issuer implements IssuerClient {
  Issuer(this.issuance);
  final Map<String, dynamic> issuance;
  HeldCredential? handedOut;
  @override
  Future<HeldCredential> issue({required String holderDid, required String credentialType}) async {
    final json = jsonDecode(jsonEncode(issuance)) as Map<String, dynamic>;
    (json['credential'] as Map)['credentialSubject']['id'] = holderDid;
    return handedOut = HeldCredential.fromIssuance(json);
  }
}

String subject(HeldCredential c) => (c.vc['credentialSubject'] as Map)['id'] as String;

Future<void> main() async {
  final issuance = jsonDecode(File('../probe/issuance.json').readAsStringSync()) as Map<String, dynamic>;
  final id = (issuance['credential'] as Map)['id'] as String;

  final store = CredentialStore();
  final client = Issuer(issuance);
  final w = WalletService(issuer: client, store: store);
  await w.requestCredential('MembershipCredential');
  final held = subject(store.byId(id)!);

  (w.credential(id)!.vc['credentialSubject'] as Map)['id'] = 'did:key:edited-via-credential(id)';
  print('A1 WalletService.credential(id) -> edit reaches the store: ${subject(store.byId(id)!)}');
  (w.heldCredentials().first.vc)['expires_at'] = 0;
  print('A2 WalletService.heldCredentials() -> edit reaches the store: expires_at=${store.byId(id)!.vc['expires_at']}');
  client.handedOut!.disclosures.clear();
  print('A3 object the IssuerClient returned is the one stored -> after the client clears its disclosures, store holds ${store.byId(id)!.disclosures.length} disclosures');
  final saved = HeldCredential.fromIssuance(jsonDecode(jsonEncode(issuance)) as Map<String, dynamic>);
  final s2 = CredentialStore()..save(saved);
  saved.vc['issuer'] = 'did:web:edited-after-save';
  print('A4 CredentialStore.save keeps the caller\'s object -> ${s2.byId(id)!.issuer}');
  print('   (holder DID originally stored: $held)');
}
EOF
dart run bin/aliasing.dart 2>&1 | tail -5

